    if n_required is None:
        return FULL_PILOT_MIN_AUTHORED_ACTIONS
    if isinstance(n_required, bool):
        return FULL_PILOT_MIN_AUTHORED_ACTIONS
    try:
        n = int(n_required)
    except (TypeError, ValueError):
        return FULL_PILOT_MIN_AUTHORED_ACTIONS
    if n <= 0:
