class DualListedAuthorshipError(ValueError):
    """A capability cannot be both agent-written and templated."""


_WRITER_ROLE_STAMP_RE = re.compile(
    r"Written by the factory WRITER role \(([^)]*)\)"
)


def agent_written_handler_ids_in_workspace(workspace: Path | str) -> List[str]:
    """Handler files whose stamped WRITER source is the coding agent.

    Ground truth for the writer-contract gate: a gate must not trust the
    writer's own status claim, so the agent-authored set is re-derived from
    the files the writer physically produced (the ``Written by the factory
    WRITER role (...)`` docstring stamp in ``app/actions/*.py``). Zero is
    ``writer_no_output`` -- templated and factory-grounded writes do not
    count.
    """
    root = Path(workspace)
    actions = root / "app" / "actions"
    if not actions.is_dir():
        return []
    ids: List[str] = []
    for path in sorted(actions.glob("*.py")):
        try:
            head = path.read_text(encoding="utf-8")[:4000]
        except OSError:
            continue
        match = _WRITER_ROLE_STAMP_RE.search(head)
        if match and is_coding_agent_source(match.group(1)):
            ids.append(path.stem)
    return ids


def is_coding_agent_source(source: Any) -> bool:
    """True for coder LLM, coder CLI, or harvested keep-path labels.

    Factory-grounded persist/event_bus emit is not the coding agent.
    Deterministic templates are not the coding agent.
    """
    text = str(source or "").strip()
    if not text:
        return False
    if text.startswith("coder LLM") or text.startswith("coder CLI"):
        return True
    if text.startswith("FACTORY_CODE_CLI"):
        return True
    if text.startswith("codewhale"):
        # Phase 5: the headless CodeWhale worker is a coding agent; its
        # stamped handlers count toward the artifact gate like any other.
        return True
    lowered = text.lower()
    return lowered in {"harvested workspace handler", "compiled-brief oneshot"}


def coding_agent_artifact_ids(sources: Optional[Mapping[str, Any]]) -> List[str]:
    return sorted(
        str(k) for k, v in (sources or {}).items() if is_coding_agent_source(v)
    )


def writer_authorship_counts(
    sources: Optional[Mapping[str, Any]],
) -> Dict[str, int]:
    src = dict(sources or {})
    written = len(coding_agent_artifact_ids(src))
    return {
        "artifacts": len(src),
        "agent_written": written,
        "templated": len(src) - written,
    }


def writer_contract_role_detail(
    capabilities: Sequence[str],
    sources: Optional[Mapping[str, Any]],
) -> str:
    counts = writer_authorship_counts(sources)
    return (
        f"{len(capabilities)} capability(ies); {counts['artifacts']} artifact(s) — "
        f"{counts['agent_written']} by the coding agent, "
        f"{counts['templated']} templated"
    )


def _dispatch_map(state_or_dispatch: Optional[Mapping[str, Any]]) -> Mapping[str, Any]:
    raw = dict(state_or_dispatch or {})
    nested = raw.get("brief_dispatch")
    if isinstance(nested, Mapping):
        return nested
    return raw


def kept_handler_ids_from(state_or_dispatch: Optional[Mapping[str, Any]]) -> List[str]:
    """``brief_dispatch.kept_handler_ids`` from state or the dispatch map itself."""
    dispatch = _dispatch_map(state_or_dispatch)
    ids: List[str] = []
    for item in dispatch.get("kept_handler_ids") or ():
        cid = str(item or "").strip()
        if cid and cid not in ids:
            ids.append(cid)
    return ids


def cli_authored_ids_from(state_or_dispatch: Optional[Mapping[str, Any]]) -> Optional[List[str]]:
    """Explicit CLI harvest ids, or None when the field was never recorded.

    An empty list after kimi/DeepSeek exit 0 is not a keep-path credit
    (``FACTORY_CODE_CLI_NO_AUTHORSHIP``). Missing key keeps #375
    ``kept_handler_ids`` promotion for real CLI keep-path receipts.
    """
    dispatch = _dispatch_map(state_or_dispatch)
    if "cli_authored_ids" not in dispatch:
        return None
    ids: List[str] = []
    for item in dispatch.get("cli_authored_ids") or ():
        cid = str(item or "").strip()
        if cid and cid not in ids:
            ids.append(cid)
    return ids


def promote_cli_keep_ids(state_or_dispatch: Optional[Mapping[str, Any]]) -> List[str]:
    """Ids inspect may credit as CLI keep-path writes.

    Prefer ``cli_authored_ids`` when present (including empty). Otherwise
    fall back to ``kept_handler_ids`` for receipts that predate that field.
    """
    authored = cli_authored_ids_from(state_or_dispatch)
    if authored is not None:
        return authored
    return kept_handler_ids_from(state_or_dispatch)


def exclusive_authorship_caps(
    caps_written: Sequence[str],
    caps_templated: Sequence[str],
) -> Tuple[List[str], List[str]]:
    """Written wins. The same capability id must not appear in both lists."""
    written = [
        c
        for c in dict.fromkeys(str(x).strip() for x in caps_written)
        if c
    ]
    written_set = set(written)
    templated = [
        c
        for c in dict.fromkeys(str(x).strip() for x in caps_templated)
        if c and c not in written_set
    ]
    return written, templated


def dual_listed_capability_ids(
    caps_written: Iterable[str],
    caps_templated: Iterable[str],
) -> List[str]:
    return sorted({str(c) for c in caps_written} & {str(c) for c in caps_templated})


def refuse_dual_listed_caps(
    caps_written: Sequence[str],
    caps_templated: Sequence[str],
) -> None:
    """Fail-closed: overlapping written+templated ids are a factory bug."""
    overlap = dual_listed_capability_ids(caps_written, caps_templated)
    if overlap:
        raise DualListedAuthorshipError(
            "capability id(s) listed as both agent-written and templated: "
            + ", ".join(overlap)
        )


def is_action_artifact_id(artifact_id: str) -> bool:
    """True for a capability action-handler id, not models/routes/extras."""
    text = str(artifact_id or "").strip()
    if not text or ":" in text or "/" in text:
        return False
    if text.endswith(".py") or text.endswith(".tsx") or text.endswith(".md"):
        return False
    if text in _NON_ACTION_ARTIFACT_IDS:
        return False
    if text.startswith("template_"):
        return False
    return True


def _as_nonneg_int(value: Any) -> Optional[int]:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, int):
        return value if value >= 0 else None
    if isinstance(value, str) and value.isdigit():
        return int(value)
    return None


def _unique_ids(values: Iterable[Any]) -> List[str]:
    ids: List[str] = []
    for item in values:
        cid = str(item or "").strip()
        if cid and cid not in ids:
            ids.append(cid)
    return ids


def _cli_ids_from_mapping(blob: Any) -> Optional[List[str]]:
    if not isinstance(blob, Mapping):
        return None
    if "cli_authored_ids" in blob:
        return _unique_ids(blob.get("cli_authored_ids") or ())
    nested = cli_authored_ids_from(blob)
    return nested


@dataclass(frozen=True)
class FullPilotAuthorship:
    """Measured action-handler authorship against the launching-ready floor."""

    action_ids: List[str] = field(default_factory=list)
    cli_authored_ids: List[str] = field(default_factory=list)
    action_py: int = 0
    measured: bool = False
    meets_floor: bool = False
    n_required: Optional[int] = None
    need: int = FULL_PILOT_MIN_AUTHORED_ACTIONS

    @property
    def below_floor(self) -> bool:
        """Unmeasured or zero authorship is below floor (0.5).

        The old path returned ``measured and not meets_floor``, so a build
        with no authorship record at all slipped past the floor silently.
        Zero artifacts can never meet the floor; unmeasured is unmeasured
        because nothing was recorded to measure.
        """
        return not (self.measured and self.meets_floor)


def full_pilot_authorship_from(
    status: Optional[Mapping[str, Any]] = None,
    workspace: Optional[Path | str] = None,
    *,
    n_required: Optional[int] = None,
    plan: Any = None,
    blueprint: Any = None,
) -> FullPilotAuthorship:
    """Count agent-written action handlers / ``cli_authored_ids``.

    ``full_pilot`` needs ≥ ``full_pilot_authorship_need(n_required)`` of
    either. Missing counts are not a pass. A present count below the
    floor is a measured refuse (VetCare action_py=3). A 4-cap golden
    with 4 authored ids meets the floor when ``n_required`` is 4.
    """
    status = dict(status or {})
    authorship = status.get("authorship")
    if not isinstance(authorship, Mapping):
        authorship = {}
    receipt = status.get("coder_receipt")
    if not isinstance(receipt, Mapping):
        receipt = {}

    resolved = n_required
    if resolved is None:
        resolved = n_required_capabilities_from(
            status, workspace, plan=plan, blueprint=blueprint
        )
    need = full_pilot_authorship_need(resolved)

    cli_ids: Optional[List[str]] = None
    for blob in (authorship, receipt, status.get("brief_dispatch")):
        found = _cli_ids_from_mapping(blob)
        if found is not None:
            cli_ids = found
            break

    action_ids: List[str] = []
    measured_actions = False
    artifacts = authorship.get("agent_artifacts")
    if isinstance(artifacts, list):
        action_ids = [cid for cid in _unique_ids(artifacts) if is_action_artifact_id(cid)]
        measured_actions = True
    explicit_action_py = _as_nonneg_int(authorship.get("action_py"))
    if explicit_action_py is not None and not measured_actions:
        measured_actions = True
        action_ids = action_ids or [f"action_{i}" for i in range(explicit_action_py)]

    action_py = len(action_ids)
    if measured_actions and explicit_action_py is not None and not artifacts:
        action_py = explicit_action_py

    if not measured_actions:
        written = _as_nonneg_int(authorship.get("agent_written"))
        if written is not None:
            measured_actions = True
            action_py = written

    cli_list = cli_ids if cli_ids is not None else []
    measured = measured_actions or cli_ids is not None
    meets = action_py >= need or len(cli_list) >= need
    return FullPilotAuthorship(
        action_ids=list(action_ids),
        cli_authored_ids=list(cli_list),
        action_py=action_py,
        measured=measured,
        meets_floor=bool(measured and meets),
        n_required=resolved,
        need=need,
    )


def thin_store_green_export_blocker(
    status: Optional[Mapping[str, Any]] = None,
    workspace: Optional[Path | str] = None,
    *,
    n_required: Optional[int] = None,
    plan: Any = None,
    blueprint: Any = None,
) -> Optional[str]:
    """Refuse a Store-green / full-pilot zip when authorship is below floor.

    Code-cycle prototypes (PRODUCT/STORE not run) are not this lie.
    """
    status = dict(status or {})
    floor = full_pilot_authorship_from(
        status,
        workspace,
        n_required=n_required,
        plan=plan,
        blueprint=blueprint,
    )
    if not floor.below_floor:
        return None
    grade = status.get("level_grade")
    gates = grade.get("three_gate") if isinstance(grade, Mapping) else None
    if not isinstance(gates, Mapping):
        from app.factory.build.level_grade import parse_three_gate_verdict

        gates = parse_three_gate_verdict(str(status.get("detail") or ""))
    cycle = str(status.get("cycle") or "").strip().lower()
    claiming_store_green = (
        cycle == "pilot"
        or (
            str(gates.get("PRODUCT") or "") == "PASS"
            and str(gates.get("STORE") or "") == "PASS"
        )
    )
    if not claiming_store_green:
        return None
    n_req = (
        f", n_required={floor.n_required}" if floor.n_required is not None else ""
    )
    return (
        "FACTORY_CODE_CLI_THIN_AUTHORSHIP: authorship is below the "
        f"full-pilot floor (action_py={floor.action_py}, "
        f"cli_authored_ids={len(floor.cli_authored_ids)}, "
        f"need ≥{floor.need}{n_req}) — will not ship a "
        "Store-green / full-pilot zip"
    )

def inventory_needs_rag(compiled: Any) -> bool:
    """True when STEP 0 names a RAG ingest/query surface.

    ``vector_search`` / ``knowledge`` binds are registry REUSE, not a
    claimed ingest/query product. Estate dual-RAG capabilities
    (``dual_rag_estate_docs``, ``dual_rag_sop``) still owe the HTTP
    contract below even when their Store binds are vector_search.
    """
    for item in getattr(compiled, "inventory", ()) or ():
        cid = str(getattr(item, "capability_id", "") or "").lower()
        if "rag" in cid:
            return True
        bids = list(getattr(item, "block_ids", ()) or ()) + list(
            getattr(item, "verified_present", ()) or ()
        )
        for bid in bids:
            name = str(bid).strip().lower()
            if name in RAG_SURFACE_IDS or name.startswith("rag_") or "dual_rag" in name:
                return True
    return False


def required_capability_ids(compiled: Any) -> List[str]:
    caps = list(getattr(compiled, "capabilities", ()) or [])
    return [str(c).strip() for c in caps if str(c).strip()]


def _workspace_root(ctx: Any) -> Path:
    ws = getattr(ctx, "workspace", None)
    if ws is None:
        return Path(".")
    return Path(getattr(ws, "workspace", ws))


def _read_if(path: Path) -> str:
    if not path.is_file():
        return ""
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        return ""


def _quoted_path_present(blob: str, path: str) -> bool:
    """True when *path* is a quoted HTTP route, not a docs/prose mention."""
    return f'"{path}"' in blob or f"'{path}'" in blob


def _app_python_sources(root: Path) -> str:
    """Concatenated ``app/**/*.py``. Docs JSON stamps are not routes."""
    app = root / "app"
    if not app.is_dir():
        return ""
    parts: List[str] = []
    for path in sorted(app.rglob("*.py")):
        parts.append(_read_if(path))
    return "\n".join(parts)


def rag_ingest_route_present(root: Path) -> bool:
    blob = _app_python_sources(root)
    return any(_quoted_path_present(blob, path) for path in RAG_INGEST_PATHS)


def rag_query_route_present(root: Path) -> bool:
    blob = _app_python_sources(root)
    return any(_quoted_path_present(blob, path) for path in RAG_QUERY_PATHS)

"""Handler for capability crop_planning.

Written by the factory WRITER role (codewhale exec)

Plans a crop cycle for one field: the agronomic yield projection is computed
by the vendored ``formula_executor`` and the plan is orchestrated as a
one-pipeline ``workflow`` run, then the record is persisted.

Scope
-----
READS  the caller's record (this capability's own columns); app.dispatch (the
       local offline block runtime); app.store (the ``crop_planning`` table).
WRITES app.dispatch.execute() results; exactly ONE row in ``crop_planning``
       through ``store.save(ENTITY, record)``.
NEVER  network / HTTP store callbacks; ``vendor/**`` (sealed); another
       capability's table; ``tests/**``.

Blocks are action-dispatched: ``action=`` is a keyword, never a payload key.
Every block input is constructed here -- the caller is never asked for
``steps``, ``custom_code`` or any other block-contract key.

Authored by the WRITER coding agent -- the factory's coder CLI, codewhale exec.
"""

from __future__ import annotations

from typing import Any, Dict, Tuple

from app.dispatch import execute

CAPABILITY_ID = "crop_planning"
ENTITY = 'crop_planning'
BLOCK_IDS = ['workflow', 'formula_executor']
#: Each block's declared default action (vendor/blocks/<id>/block.json).
BLOCK_DEFAULT_ACTIONS = {'workflow': 'run', 'formula_executor': 'execute'}
#: This capability's own domain columns. The kernel strips trust-scope keys
#: from caller arguments, so the names must be declared here as domain data.
CAPABILITY_FIELDS = ['reference', 'crop_name', 'field_name', 'area_hectares', 'planting_date', 'harvest_date', 'rotation_group', 'status', 'notes']

#: The envelope vocabulary, enforced at the handler edge too, so a direct
#: handle() call cannot store a status the schema forbids.
STATUS_VALUES = ("open", "in_progress", "closed")
REQUIRED_FIELDS = ("reference", "crop_name", "field_name", "status")

_FAILURE_STATUSES = frozenset({"error", "failed", "failure", "partial", "timeout"})

#: Agronomic projection used when the caller does not state a yield target.
#: Tonnes per hectare from the rotation group the plan was filed under.
DEFAULT_YIELD_TONNES_PER_HECTARE = 4.2
ROTATION_YIELD_TONNES_PER_HECTARE = {
    "cereal": 5.5,
    "legume": 3.1,
    "oilseed": 2.8,
    "fallow": 0.0,
}


def _persist_record(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Factory-grounded one-record persist. PRODUCT re-reads this entity.

    ``store`` is imported here, not at module load: an isolated contract probe
    execs this file against the factory ``app`` package, which has no product
    ``app.store``. A generated workspace always has one.
    """
    record = {k: v for k, v in (payload or {}).items() if k in CAPABILITY_FIELDS}
    try:
        from app import store as _store
    except ImportError:  # pragma: no cover - isolated contract probe
        return record
    return _store.save(ENTITY, record)


def _prepare(block_id: str, block_input: Dict[str, Any], action: str) -> Dict[str, Any]:
    """Shape a constructed block input into what the block actually accepts.

    ``prepare_block_input`` fills only keys that are missing, so every value
    built here survives; ``split_execute_action`` lifts ``action`` out of the
    payload so the operation travels as the keyword only.
    """
    from app.block_inputs import prepare_block_input, split_execute_action

    resolved, data = split_execute_action(
        block_input, action=action, default_action=action
    )
    return prepare_block_input(
        block_id,
        data,
        action=resolved,
        roster=BLOCK_IDS,
        entity=ENTITY,
        default_actions=BLOCK_DEFAULT_ACTIONS,
    )


def _is_failure(result: Any) -> bool:
    """Did this block call fail? ``ok is False``/``error``/error statuses are."""
    if not isinstance(result, dict):
        return False
    if result.get("ok") is False or "error" in result:
        return True
    if str(result.get("status") or "").lower() in _FAILURE_STATUSES:
        return True
    steps = result.get("results")
    if isinstance(steps, list):
        for step in steps:
            if isinstance(step, dict) and str(step.get("status") or "").lower() in _FAILURE_STATUSES:
                return True
    return False


def _yield_target(crop_name: str, rotation_group: str) -> float:
    """Tonnes per hectare this rotation is planned against."""
    key = str(rotation_group or "").strip().lower()
    if key in ROTATION_YIELD_TONNES_PER_HECTARE:
        return ROTATION_YIELD_TONNES_PER_HECTARE[key]
    if str(crop_name or "").strip().lower() in ROTATION_YIELD_TONNES_PER_HECTARE:
        return ROTATION_YIELD_TONNES_PER_HECTARE[str(crop_name).strip().lower()]
    return DEFAULT_YIELD_TONNES_PER_HECTARE


def _yield_inputs(record: Dict[str, Any]) -> Dict[str, Any]:
    """The formula_executor variable set, derived from the caller's record."""
    area = record.get("area_hectares")
    try:
        area = float(area)
    except (TypeError, ValueError):
        area = 0.0
    return {
        "area_hectares": area,
        "yield_per_hectare": _yield_target(record.get("crop_name", ""), record.get("rotation_group", "")),
    }


def _yield_formula() -> Dict[str, Any]:
    """A real agronomic projection, executed by the vendored formula block."""
    return {
        "operation": "execute",
        "formula_description": (
            "AgriSphere crop yield projection: area_hectares * yield_per_hectare"
        ),
        "custom_code": (
            "result = round(area_hectares * yield_per_hectare, 2)\n"
            "projected_tonnes = result"
        ),
        "input_values": {},
    }


def _governance_window(record: Dict[str, Any]) -> str:
    """Planting/harvest span this plan covers, as the pipeline summary."""
    planting = str(record.get("planting_date") or "unscheduled")
    harvest = str(record.get("harvest_date") or "unscheduled")
    return f"{planting} -> {harvest}"


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Plan one crop cycle, run its blocks, then persist exactly one record."""
    if not isinstance(payload, dict):
        return {"ok": False, "capability": CAPABILITY_ID, "error": "payload must be an object"}

    record = {k: v for k, v in payload.items() if k in CAPABILITY_FIELDS}
    missing = [name for name in REQUIRED_FIELDS if record.get(name) in (None, "")]
    if missing:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "Missing required field: " + ", ".join(missing),
        }
    if record.get("status") not in STATUS_VALUES:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "status must be one of: " + ", ".join(STATUS_VALUES),
        }

    variables = _yield_inputs(record)
    formula = _yield_formula()
    formula["input_values"] = variables
    window = _governance_window(record)

    plan: "Tuple[Tuple[str, Dict[str, Any]], ...]" = (
        ("formula_executor", formula),
        (
            "workflow",
            {
                "steps": [
                    {
                        "block": "formula_executor",
                        "action": BLOCK_DEFAULT_ACTIONS["formula_executor"],
                        "input": dict(formula),
                    }
                ],
                "result": {
                    "reference": record.get("reference"),
                    "field_name": record.get("field_name"),
                    "window": window,
                },
            },
        ),
    )

    results: Dict[str, Any] = {}
    errors: Dict[str, str] = {}
    for block_id, block_input in plan:
        action = BLOCK_DEFAULT_ACTIONS.get(block_id)
        prepared = _prepare(block_id, block_input, action)
        try:
            outcome = execute(block_id, prepared, action=action)
        except Exception as exc:  # a block that cannot load is a refusal too
            outcome = {"status": "error", "error": f"{type(exc).__name__}: {exc}"}
        results[block_id] = outcome
        if _is_failure(outcome):
            errors[block_id] = str(outcome.get("error") or outcome.get("status"))[:200]

    if errors:
        return {
            "ok": False,
            "capability": CAPABILITY_ID,
            "error": "; ".join(f"{b}: {e}" for b, e in sorted(errors.items())),
            "results": results,
        }

    projection = results.get("formula_executor") or {}
    stored = _persist_record(record)
    return {
        "ok": True,
        "capability": CAPABILITY_ID,
        "entity": ENTITY,
        "plan": {
            "reference": record.get("reference"),
            "crop_name": record.get("crop_name"),
            "field_name": record.get("field_name"),
            "window": window,
            "inputs": variables,
        },
        "projection": {
            "tonnes_per_hectare": variables["yield_per_hectare"],
            "area_hectares": variables["area_hectares"],
            "projected_tonnes": projection.get("execution_result"),
        },
        "stored": stored,
        "results": results,
    }
