"""Domain models for this platform.

Plain dataclasses on purpose: the delivered platform must run with no
ORM, no service, and no network. Persistence is in app/store.py.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from typing import Any, Dict, Optional


@dataclass
class ComplianceDocumentation:
    """Entity for capability compliance_documentation."""

    id: Optional[int] = None
    reference: str = ""
    document_type: str = 'pesticide_application'
    jurisdiction: str = ""
    issued_date: str = '2026-09-03'
    expiry_date: str = '2026-09-03'
    attachment_path: str = ""
    status: str = 'open'
    notes: str = ""

    FIELDS = ['reference', 'document_type', 'jurisdiction', 'issued_date', 'expiry_date', 'attachment_path', 'status', 'notes']
    CONSTRAINTS = {'reference': {'required': True}, 'document_type': {'allowed_values': ['pesticide_application', 'organic_certification', 'inspection', 'training_record'], 'required': True}, 'jurisdiction': {'required': False}, 'issued_date': {'required': False}, 'expiry_date': {'required': False}, 'attachment_path': {'required': False}, 'status': {'allowed_values': ['open', 'in_progress', 'closed'], 'required': True}, 'notes': {'required': False}}
    _FIELD_PY = {}
    _FIELD_JSON = {}

    def to_dict(self) -> Dict[str, Any]:
        raw = asdict(self)
        return {self._FIELD_JSON.get(k, k): v for k, v in raw.items()}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "ComplianceDocumentation":
        known = {}
        for k, v in (data or {}).items():
            if k == "id":
                continue
            attr = cls._FIELD_PY.get(k, k)
            if k in cls.FIELDS or attr in cls._FIELD_JSON:
                known[attr] = v
        return cls(id=(data or {}).get("id"), **known)


