import React, { useCallback, useMemo, useState } from "react";
import { Json, createRecord, isRefusal, refusalReason } from "../api";

const ROUTES: Array<{ capability: string; keywords: string[] }> = [
  { capability: "crop_planning", keywords: ["plant", "sow", "crop", "harvest", "field plan"] },
  { capability: "inventory_management", keywords: ["stock", "seed", "fertiliser", "pesticide", "reorder"] },
  { capability: "compliance_documentation", keywords: ["certificate", "compliance", "audit", "record", "inspection"] },
  { capability: "market_analytics", keywords: ["price", "market", "demand", "sell", "profit"] },
  { capability: "farm_operations_tracking", keywords: ["irrigat", "labour", "equipment", "activity", "spray"] },
  { capability: "weather_and_risk_alerts", keywords: ["frost", "storm", "drought", "pest", "alert"] },
  { capability: "supply_chain_coordination", keywords: ["order", "delivery", "buyer", "supplier", "shipment"] },
];

export function routePrompt(prompt: string): string {
  const text = prompt.toLowerCase();
  for (const route of ROUTES) {
    if (route.keywords.some((keyword) => text.includes(keyword))) {
      return route.capability;
    }
  }
  return "farm_operations_tracking";
}

